macro_rules! deps {
    () => {
        DFA!();
        LookMatcher!();
    };
}

macro_rules! Start {
    () => {
        deps!();
        # [doc = " Represents the six possible starting configurations of a DFA search."] # [doc = ""] # [doc = " The starting configuration is determined by inspecting the beginning"] # [doc = " of the haystack (up to 1 byte). Ultimately, this along with a pattern ID"] # [doc = " (if specified) and the type of search (anchored or not) is what selects the"] # [doc = " start state to use in a DFA."] # [doc = ""] # [doc = " As one example, if a DFA only supports unanchored searches and does not"] # [doc = " support anchored searches for each pattern, then it will have at most 6"] # [doc = " distinct start states. (Some start states may be reused if determinization"] # [doc = " can determine that they will be equivalent.) If the DFA supports both"] # [doc = " anchored and unanchored searches, then it will have a maximum of 12"] # [doc = " distinct start states. Finally, if the DFA also supports anchored searches"] # [doc = " for each pattern, then it can have up to `12 + (N * 6)` start states, where"] # [doc = " `N` is the number of patterns."] # [doc = ""] # [doc = " Handling each of these starting configurations in the context of DFA"] # [doc = " determinization can be *quite* tricky and subtle. But the code is small"] # [doc = " and can be found at `crate::util::determinize::set_lookbehind_from_start`."] # [derive (Clone , Copy , Debug , Eq , PartialEq)] pub (crate) enum Start { # [doc = " This occurs when the starting position is not any of the ones below."] NonWordByte = 0 , # [doc = " This occurs when the byte immediately preceding the start of the search"] # [doc = " is an ASCII word byte."] WordByte = 1 , # [doc = " This occurs when the starting position of the search corresponds to the"] # [doc = " beginning of the haystack."] Text = 2 , # [doc = " This occurs when the byte immediately preceding the start of the search"] # [doc = " is a line terminator. Specifically, `\\n`."] LineLF = 3 , # [doc = " This occurs when the byte immediately preceding the start of the search"] # [doc = " is a line terminator. Specifically, `\\r`."] LineCR = 4 , # [doc = " This occurs when a custom line terminator has been set via a"] # [doc = " `LookMatcher`, and when that line terminator is neither a `\\r` or a"] # [doc = " `\\n`."] # [doc = ""] # [doc = " If the custom line terminator is a word byte, then this start"] # [doc = " configuration is still selected. DFAs that implement word boundary"] # [doc = " assertions will likely need to check whether the custom line terminator"] # [doc = " is a word byte, in which case, it should behave as if the byte"] # [doc = " satisfies `\\b` in addition to multi-line anchors."] CustomLineTerminator = 5 , }
    };
}

Start!()